head.script:
scwin.vScrenID = 'ULDBNS15000.xml';
///////// 1. 변수 및 선언 영역 /////////
scwin.vMktactCd = '308'; // 채권시장조치구분코드
scwin.vBndListProcsTpCd = 1; // 채권처리구분(1:신청,2:접수)
scwin.vDtlInfoRowCount = 0;
scwin.vViewYN = 'N';
scwin.vRowPos = 0;
scwin.vIsuCd = '';
scwin.hasAttachDoc = '';
scwin.gBndApplId = '';
scwin.gProcsStat = '';
scwin.fn_GetPar = null; // 팝업 파라미터 전달 함수($c.bns 팝업 규약)
scwin.fn_SetPar = null; // 팝업 결과 수신 함수($c.bns 팝업 규약)
scwin.processGp = ''; // 접수 1, 반송 2, 처리완료 3, 수정 4, 팀장확인 6, 표준코드요청 9
scwin.btnStat = {};
scwin.arrPar = [];
scwin.jobtitl = ''; // 직위구분(팀장확인 권한 체크용)
scwin.duty = '';
scwin.dutyChrg = '';
scwin.empNo = '';
scwin.empNm = '';

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 01
 * @description 페이지로드 — 사용자 정보 조회, 목록 조회 및 탭 상태 반영
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.empNo = $c.session.getUserInfo("empNo");   // 사원번호
        scwin.empNm = $c.session.getUserInfo("empNm");   // 사용자이름
        scwin.jobtitl = $c.session.getUserInfo("jobtitl");
        scwin.duty = $c.session.getUserInfo("duty");
        scwin.dutyChrg = $c.session.getUserInfo("dutyChrg");

        scwin.vBndListProcsTpCd = tab_List.getSelectedTabIndex() + 1;
        await scwin.listSync(); // 목록 조회

        // 필드 ReadOnly 속성 제거/부여
        scwin.chgTabAct(scwin.vBndListProcsTpCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.onpageload" });
    }
};

/**
 * @method
 * @name scwin.onpageunload
 * @author Inswave
 * @date 2026. 09. 01
 * @description 페이지 종료
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageunload = function () {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.dlt_searchList_onrowpositionchange
 * @author Inswave
 * @date 2026. 09. 01
 * @description 목록 행 선택 변경 — 선택 행 키 보관 후 상세 조회, 처리완료 버튼 상태 갱신
 * @param {Object} info 행 위치 변경 정보
 * @returns
 * @hidden N
*/
scwin.dlt_searchList_onrowpositionchange = function (info) {
    try {
        const row = info.newRowIndex;
        scwin.vRowPos = row;
        if (row > -1) {
            scwin.gBndApplId = dlt_searchList.getCellData(row, "bndApplId");
            scwin.gProcsStat = dlt_searchList.getCellData(row, "procsStat");
            $p.setTimeout(function () {
                // 상세조회(완료 시 신고담당자 목록 조회 포함) — 타이머 콜백은 진입점 try/catch 밖이므로 자체 처리
                scwin.dtlSync().catch(function (ex) {
                    $c.exception.handleError(ex, { context: "ULDBNS15000.dtlSync" });
                });
            }, {"delay": 20});
            scwin.procBtnStat(); // 처리완료 버튼 활성/비활성
        } else {
            dma_detailList.setEmptyValue();
            dlt_list3.removeAll();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context: "ULDBNS15000.dlt_searchList_onrowpositionchange" });
    }
};

/**
 * @method
 * @name scwin.tab_List_ontabclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description 신청내역/접수내역 탭 클릭 — 처리구분 변경 후 목록 재조회 및 입력필드 ReadOnly 갱신
 * @param {String} tabId 탭 id
 * @param {Number} index 탭 index
 * @returns
 * @hidden N
*/
scwin.tab_List_ontabclick = async function (tabId, index) {
    try {
        scwin.vBndListProcsTpCd = index + 1;
        await scwin.listSync(); // 목록 조회
        // 필드 ReadOnly 속성 제거/부여
        scwin.chgTabAct(scwin.vBndListProcsTpCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.tab_List_ontabclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Search_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [조회] 클릭(신청내역 탭) — 목록 조회
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Search_onclick = async function () {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.listSync" });
    }
};

/**
 * @method
 * @name scwin.btn_Search2_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [조회] 클릭(접수내역 탭) — 목록 조회
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Search2_onclick = async function () {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.listSync" });
    }
};

/**
 * @method
 * @name scwin.btn_Acpt_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [접수] 클릭 — 신청데이터 접수 처리
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Acpt_onclick = async function () {
    if (scwin.vDtlInfoRowCount === 0) return;
    try {
        scwin.processGp = '1';
        await scwin.acpt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.acpt" });
    }
};

/**
 * @method
 * @name scwin.btn_Ret_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [반송] 클릭(신청내역 탭) — 반송 팝업 호출(AS-IS 주석 상태 유지)
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Ret_onclick = function () {
    try {
        if (scwin.vDtlInfoRowCount === 0) return;
        scwin.processGp = '2';
        // scwin.fn_GetPar = scwin.getReturn;
        // scwin.fn_SetPar = scwin.setReturn;
        // $c.bns.fn_PopReturn(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS15000.btn_Ret_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Ret2_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [반송] 클릭(접수내역 탭) — 수정/반송 가능 여부 체크 후 반송 팝업 호출
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Ret2_onclick = async function () {
    if (scwin.vDtlInfoRowCount === 0) return;
    try {
        // 접수 후 수정 및 반송시 체크한다.
        if (await scwin.checkModAndRet(scwin.gBndApplId) > 0) return;
        scwin.processGp = '2';
        scwin.fn_GetPar = scwin.getReturn;
        scwin.fn_SetPar = scwin.setReturn;
        $c.bns.fn_PopReturn(grd_List1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.checkModAndRet" });
    }
};

/**
 * @method
 * @name scwin.btn_Attach_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [첨부파일확인] 클릭 — 첨부/팩스문서 목록 팝업 호출
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Attach_onclick = function () {
    if (scwin.vDtlInfoRowCount === 0) return;
    try {
        if (dma_detailList.get("hasAttachDoc") === "N") {
            $c.win.alert("연결된 팩스/첨부문서가 없습니다.");
            return;
        }
        scwin.fn_GetPar = scwin.getCommonKey;
        $c.bns.fn_PopAttachDocSearch(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context: "ULDBNS15000.btn_Attach_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Dtl_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [종목상세내역] 클릭 — 종목상세 팝업 호출
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Dtl_onclick = function () {
    if (scwin.vDtlInfoRowCount === 0) return;
    try {
        scwin.fn_GetPar = scwin.getParIsuDelInfo;
        $c.bns.fn_PopIsuDetail(grd_List1);
    } catch (ex) {
        $c.exception.handleError(ex, { context: "ULDBNS15000.btn_Dtl_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_ApprovFileCreat_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [결재파일생성] 클릭 — 결재파일생성 팝업(ULDBNS90005) 오픈
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_ApprovFileCreat_onclick = async function () {
    try {
        scwin.getParApprovFileWrt(scwin.arrPar);

        const url = "/ui/bns/bnscommon/ULDBNS90005.xml";
        const options = {
            id: "ULDBNS90005",
            popupName: "결재파일생성",
            frameModal: "top",
            width: "600px",
            height: "500px"
        };
        await $c.win.openPopup(url, options, scwin.arrPar);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.btn_ApprovFileCreat_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Proc_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [처리완료] 클릭 — 처리완료 처리
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Proc_onclick = async function () {
    if (scwin.vDtlInfoRowCount === 0) return;
    if (scwin.btnStat.Proc === "dis") return;
    try {
        scwin.vRowPos = dlt_searchList.getRowPosition();
        scwin.processGp = '3';
        await scwin.procsComplt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.procsComplt" });
    }
};

/**
 * @method
 * @name scwin.btn_Mod_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [수정] 클릭 — 접수 후 수정 처리
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_Mod_onclick = async function () {
    if (scwin.vDtlInfoRowCount === 0) return;
    try {
        scwin.vRowPos = dlt_searchList.getRowPosition();
        scwin.processGp = '4';
        await scwin.procsComplt();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.procsComplt" });
    }
};

/**
 * @method
 * @name scwin.btn_TeamleadrConfrm_onclick
 * @author Inswave
 * @date 2026. 09. 01
 * @description [팀장확인] 클릭 — 팀장확인 처리
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_TeamleadrConfrm_onclick = async function () {
    try {
        // 현업요청으로 팀장확인 추가 jackal_140804
        scwin.vRowPos = dlt_searchList.getRowPosition();
        scwin.processGp = "6";
        const confrmDd = dlt_searchList.getCellData(dlt_searchList.getRowPosition(), "teamleaderConfrmDd");
        await scwin.teamleadrConfrm1(confrmDd, scwin.gBndApplId, scwin.vBndListProcsTpCd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDBNS15000.teamleadrConfrm1" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.sbm_searchList_submitdone
 * @author Inswave
 * @date 2026. 09. 01
 * @description 목록 조회 후처리 — 기존 선택 행 복원, 실패 시 오류 알림
 * @param {Object} e 통신 응답 객체(resObj)
 * @returns
 * @hidden N
*/
scwin.sbm_searchList_submitdone = async function (e) {
    if (e.responseStatusCode === 200) {
        dlt_searchList.setRowPosition(0);
        // 접수, 수정, 처리완료, 팀장확인 시 해당 ROW로 이동
        scwin.rowPos(dlt_searchList, scwin.vRowPos);
    } else {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
};

/**
 * @method
 * @name scwin.sbm_detail_submitdone
 * @author Inswave
 * @date 2026. 09. 01
 * @description 상세 조회 후처리 — 채권신고담당자 조회 및 상세 건수 보관
 * @param {Object} e 통신 응답 객체(resObj)
 * @returns
 * @hidden N
*/
scwin.sbm_detail_submitdone = async function (e) {
    if (e.responseStatusCode === 200) {
        await scwin.search2(); // 채권신고담당자 조회
        scwin.vDtlInfoRowCount = dma_detailList.getCount();
    } else {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
};

/**
 * @method
 * @name scwin.sbm_save_submitdone
 * @author Inswave
 * @date 2026. 09. 01
 * @description 접수 처리 후처리 — 처리구분별 완료 알림 후 목록 재조회
 * @param {Object} e 통신 응답 객체(resObj)
 * @returns
 * @hidden N
*/
scwin.sbm_save_submitdone = async function (e) {
    if (scwin.processGp === '1') {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "접수"));
    }
    if (scwin.processGp === '3') {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    }
    if (scwin.processGp === '6') {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
    }
    await scwin.listSync();
};

/**
 * @method
 * @name scwin.sbm_modify_submitdone
 * @author Inswave
 * @date 2026. 09. 01
 * @description 수정 처리 후처리 — 결과 알림 후 목록 재조회
 * @param {Object} e 통신 응답 객체(resObj)
 * @returns
 * @hidden N
*/
scwin.sbm_modify_submitdone = async function (e) {
    if (e.responseStatusCode !== 200) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    } else {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        await scwin.listSync();
    }
};

/**
 * @method
 * @name scwin.sbm_procComplt_submitdone
 * @author Inswave
 * @date 2026. 09. 01
 * @description 처리완료 후처리 — 결과 알림 후 목록 재조회
 * @param {Object} e 통신 응답 객체(resObj)
 * @returns
 * @hidden N
*/
scwin.sbm_procComplt_submitdone = async function (e) {
    if (e.responseStatusCode !== 200) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002", "처리완료"));
    } else {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        await scwin.listSync();
    }
};

/**
 * @method
 * @name scwin.sbm_teamLeaderConfirm_submitdone
 * @author Inswave
 * @date 2026. 09. 01
 * @description 팀장확인 후처리 — 처리구분별 완료 알림 후 목록 재조회
 * @param {Object} e 통신 응답 객체(resObj)
 * @returns
 * @hidden N
*/
scwin.sbm_teamLeaderConfirm_submitdone = async function (e) {
    if (scwin.processGp === '1') {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "접수"));
    }
    if (scwin.processGp === '3') {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    }
    if (scwin.processGp === '4') {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    }
    if (scwin.processGp === '6') {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "팀장확인"));
    }
    await scwin.listSync();
};

/**
 * @method
 * @name scwin.listSync
 * @author Inswave
 * @date 2026. 09. 01
 * @description 목록조회 — 탭의 처리구분 기준으로 신청/접수 목록 조회
 * @param
 * @returns
 * @hidden N
*/
scwin.listSync = async function () {
    dma_search.set("vBndListProcsTpCd", scwin.vBndListProcsTpCd);
    dma_search.set("vMktactCd", scwin.vMktactCd);

    const sbmOptions = {
        id: "sbm_searchList",
        action: "/api/bonds/chgList/chgCoupnRt/chgCoupnRtList-select",
        method: "get",
        ref: "dma_search=body",
        target: "dlt_searchList=body",
        gridview: "grd_List1,grd_List2",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_searchList_submitdone(sbmRtn);
};

/**
 * @method
 * @name scwin.dtlSync
 * @author Inswave
 * @date 2026. 09. 01
 * @description 상세조회 — 선택 행의 표면이자율 변경 신청 상세 조회
 * @param
 * @returns
 * @hidden N
*/
scwin.dtlSync = async function () {
    dma_detail.set("vBndListProcsTpCd", scwin.vBndListProcsTpCd);
    dma_detail.set("vMktactCd", scwin.vMktactCd);
    dma_detail.set("vBndApplId", scwin.gBndApplId);
    dma_detail.set("vViewYn", scwin.vViewYN);

    const sbmOptions = {
        id: "sbm_detailList",
        action: "/api/bonds/chgList/chgCoupnRt/chgCoupnRtDetail-select",
        method: "get",
        ref: "dma_detail=body",
        target: "dma_detailList=body",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_detail_submitdone(sbmRtn);
};

/**
 * @method
 * @name scwin.search2
 * @author Inswave
 * @date 2026. 09. 01
 * @description 채권신고담당자 조회 — 선택 행의 발행기관 기준
 * @param
 * @returns
 * @hidden N
*/
scwin.search2 = async function () {
    dlt_list3.removeAll();

    const isurCd = dlt_searchList.getCellData(dlt_searchList.getRowPosition(), "isurCd");
    dma_Param.set("vIsurCd", isurCd); // 발행기관

    const sbmOptions = {
        id: "sbm_searchChrgList",
        action: "/api/bonds/chgList/chgCoupnRt/chgCoupnRtChrg-select",
        method: "get",
        ref: "dma_Param=body",
        target: "dlt_list3=body",
        gridview: "grd_List3",
        isProcessMsg: false
    };

    await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name scwin.acpt
 * @author Inswave
 * @date 2026. 09. 01
 * @description 신청데이터를 접수 처리한다 — 공통 체크·첨부 확인·복수조치 체크 후 접수 전송
 * @param
 * @returns
 * @hidden N
*/
scwin.acpt = async function () {
    // 접수, 처리완료 공통 체크
    if (await scwin.acptProcsCheck() > 0) return;

    // 첨부문서 체크
    if (! await scwin.endConfirm(scwin.hasAttachDoc, '접수')) return;

    // 복수조치 체크
    if (await scwin.checkMultActImpsblRule(scwin.vIsuCd, scwin.vMktactCd, edt_StrtDd.getValue()) > 0) return;

    dma_Param.set("empNo", scwin.empNo);
    dma_Param.set("empNm", scwin.empNm);
    dma_Param.set("mktactTpCd", scwin.vMktactCd);
    dts_DtlInfo_CoupnRt.setJSON(dma_detailList.getJSON());
    dts_Param.setJSON(dma_Param.getJSON());

    const sbmOptions = {
        id: "sbm_save",
        action: "/api/bonds/chgList/chgCoupnRt/chgCoupnRtAcpt-proc",
        method: "post",
        ref: "dts_Param,dts_DtlInfo_CoupnRt",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_save_submitdone(sbmRtn);
};

/**
 * @method
 * @name scwin.procsComplt
 * @author Inswave
 * @date 2026. 09. 01
 * @description 처리완료 및 수정을 처리한다 — 체크 통과 후 처리구분(4: 수정, 그 외: 처리완료)별 전송
 * @param
 * @returns
 * @hidden N
*/
scwin.procsComplt = async function () {
    // 마이너스 금리 체크 (처리완료 및 수정만 체크)
    if (await scwin.minusGumriCheck() > 0) return;

    // 접수, 처리완료 공통 체크
    if (await scwin.acptProcsCheck() > 0) return;

    // 복수조치 체크
    if (await scwin.checkMultActImpsblRuleProcEnd(scwin.vIsuCd, scwin.vMktactCd, edt_StrtDd.getValue()) > 0) return;

    if (scwin.processGp === '4') {
        // 접수 후 수정 및 반송시 체크한다.
        if (await scwin.checkModAndRet(scwin.gBndApplId) > 0) return;

        if (! await $c.win.confirm("수정하시겠습니까?")) return;

        dma_Param.set("empNo", scwin.empNo);
        dma_Param.set("empNm", scwin.empNm);
        dma_Param.set("mktactTpCd", scwin.vMktactCd);
        dts_DtlInfo_CoupnRt.setJSON(dma_detailList.getJSON());
        dts_Param.setJSON(dma_Param.getJSON());

        const sbmOptions = {
            id: "sbm_modify",
            action: "/api/bonds/chgList/chgCoupnRt/chgCoupnRtSave-proc",
            method: "post",
            ref: "dts_Param,dts_DtlInfo_CoupnRt",
            isProcessMsg: false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        await scwin.sbm_modify_submitdone(sbmRtn);
    } else {
        if (! await scwin.endConfirm(scwin.hasAttachDoc, '처리완료')) return;

        dma_Param.set("empNo", scwin.empNo);
        dma_Param.set("empNm", scwin.empNm);
        dma_Param.set("mktactTpCd", scwin.vMktactCd);
        dts_DtlInfo_CoupnRt.setJSON(dma_detailList.getJSON());
        dts_Param.setJSON(dma_Param.getJSON());

        const sbmOptions = {
            id: "sbm_procComplt",
            action: "/api/bonds/chgList/chgCoupnRt/chgCoupnRt-procComplt",
            method: "post",
            ref: "dts_Param,dts_DtlInfo_CoupnRt",
            isProcessMsg: false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        await scwin.sbm_procComplt_submitdone(sbmRtn);
    }
};

/**
 * @method
 * @name scwin.teamleadrConfrm1
 * @author Inswave
 * @date 2026. 09. 01
 * @description 팀장확인을 처리한다 — 권한/재처리 확인 후 팀장확인 전송
 * @param {String} confrmDd 기존 팀장확인일
 * @param {String} vBndApplId 채권신청ID
 * @param {Number} vBndListProcsTpCd 채권처리구분(1:신청,2:접수)
 * @returns
 * @hidden N
*/
scwin.teamleadrConfrm1 = async function (confrmDd, vBndApplId, vBndListProcsTpCd) {
    // 담당자는 팀장확인 안됨.
    if (scwin.jobtitl === '03' && (scwin.duty === 'N' && scwin.dutyChrg === 'N')) {
        $c.win.alert('팀장권한만 가능합니다.');
        return;
    }

    if (confrmDd !== undefined && confrmDd !== '-' && confrmDd !== '') {
        if (! await $c.win.confirm("이미 팀장확인처리되었습니다. 재처리하실경우 다시 시장지파일이 전송됩니다.\n팀장확인처리하시겠습니까?")) {
            return;
        }
    } else {
        if (! await $c.win.confirm("팀장확인처리일자가 시장지파일 전송일자입니다.\n팀장확인처리하시겠습니까?")) {
            return;
        }
    }

    dma_chkTeamLeader.set("bndApplId", vBndApplId);
    dma_chkTeamLeader.set("bndListProcsTpCd", vBndListProcsTpCd);

    const sbmOptions = {
        id: "sbm_teamLeaderConfirm",
        action: "/api/bonds/chgList/chgCoupnRt/chgCoupnRtAcpt-teamLeaderConfirm",
        method: "get",
        ref: "dma_chkTeamLeader=body",
        isProcessMsg: false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    await scwin.sbm_teamLeaderConfirm_submitdone(sbmRtn);
};

/**
 * @method
 * @name scwin.checkMultActImpsblRule
 * @author Inswave
 * @date 2026. 09. 01
 * @description 해당종목의 복수조치 건이 접수되어 있는지 체크
 * @param {String} vIsuCd 표준코드(종목코드)
 * @param {String} vMktactCd 시장조치구분코드
 * @param {String} vStrtDd 적용일
 * @returns {Number} 0: 진행, 1: 중단
 * @hidden N
*/
scwin.checkMultActImpsblRule = async function (vIsuCd, vMktactCd, vStrtDd) {
    dma_chkIsMult.set("vStdCd", vIsuCd);
    dma_chkIsMult.set("vBndMktactTpCd", vMktactCd);
    dma_chkIsMult.set("vStrtDd", vStrtDd);

    const sbmOptions = {
        id: "sbm_checkMultActImpsblRule",
        action: "/api/bonds/bndCommon/multActImpsblRule-chk",
        method: "get",
        ref: "dma_chkIsMult=body",
        target: "dma_rtnchkIsMult=body",
        isProcessMsg: false
    };

    await $c.sbm.executeDynamic(sbmOptions);

    if (dma_rtnchkIsMult.get('MULTACT_IMPSBL_CNT') > 0) {
        let output = '복수조치가 불가능한 시장조치입니다.';
        output += '\n' + '해당종목에 대하여 적용일이 동일한 신청내역을 검토하여 주십시오.';
        $c.win.alert(output);
        return 1;
    }
    return 0;
};

/**
