 * @hidden N
*/
scwin.checkMultActImpsblRuleProcEnd = async function (vIsuCd, vMktactCd, vStrtDd) {
    dma_chkMltActImpsblProcEnd.set("vStdCd", vIsuCd);
    dma_chkMltActImpsblProcEnd.set("vBndMktactTpCd", vMktactCd);
    dma_chkMltActImpsblProcEnd.set("vStrtDd", vStrtDd);

    const sbmOptions = {
        id: "sbm_checkMultActImpsblRuleProcEnd",
        action: "/api/bonds/bndCommon/multActImpsblRuleProc-chk",
        method: "get",
        ref: "dma_chkMltActImpsblProcEnd=body",
