 * @author Inswave
 * @date 2026. 09. 01
 * @description 목록 재조회 시 기존 선택 ROW로 이동
 * @param {Object} dtsObj DataList 객체
 * @param {Number} vRowPos 이동할 행 index
 * @returns
 * @hidden N
*/
scwin.rowPos = function (dtsObj, vRowPos) {
    dtsObj.setRowPosition(vRowPos);
};

/**
 * @method
 * @name scwin.inputCheck
 * @author Inswave
 * @date 2026. 09. 01
 * @description 필수 입력 값을 체크한다 — 공통 검증(validateDataCollect)으로 적용일(필수·날짜 형식)·변경후 이자율(필수) 검증
 * @param
 * @returns {Boolean} 통과 여부
 * @hidden N
*/
scwin.inputCheck = async function () {
    return $c.validate.validateDataCollect(pnl_DtlInfo, {
        fields: {
            edt_StrtDd: { required: true, format: "date", name: "적용일" },
            edt_AfchgCpnIntRt: { required: true, name: "변경후 이자율" }
        }
    });
};

/**
 * @method
 * @name scwin.minusGumriOK
 * @author Inswave
 * @date 2026. 09. 01
 * @description 마이너스 금리 입력 확인
 * @param {Object} obj 입력 컴포넌트
 * @param {String} msg 항목명
 * @returns {Boolean} true: 진행, false: 중단
 * @hidden N
*/
scwin.minusGumriOK = async function (obj, msg) {
    const objRt = obj.getValue();
    if (objRt < 0) {
        if (! await $c.win.confirm('[' + msg + '] 마이너스(-) 값을 입력하셨습니다.\n이대로 처리하시겠습니까?')) {
            obj.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name scwin.minusGumriCheck
 * @author Inswave
 * @date 2026. 09. 01
 * @description 마이너스 금리 일괄 체크
 * @param
 * @returns {Number} 0: 진행, 1: 중단
 * @hidden N
*/
scwin.minusGumriCheck = async function () {
    return (await scwin.minusGumriOK(edt_AfchgCpnIntRt, '변경후 표면이자율')) ? 0 : 1;
};

/**
 * @method
 * @name scwin.acptProcsCheck
 * @author Inswave
 * @date 2026. 09. 01
 * @description 접수, 처리완료 시 공통 체크 구문 — 필수값·적용일 체크
 * @param
 * @returns {Number} 0: 진행, 1: 중단
 * @hidden N
*/
scwin.acptProcsCheck = async function () {
    // 필수입력값 체크
    if (! await scwin.inputCheck()) return 1;

    scwin.vIsuCd = dma_detailList.get("isuCd");
    scwin.hasAttachDoc = dma_detailList.get("hasAttachDoc");

    // 적용일,매매일,마감일,채권마감 체크
    if (await scwin.checkCmData(edt_StrtDd.getValue(), scwin.gBndApplId) > 0) return 1;

    return 0;
};

/**
 * @method
 * @name scwin.getCommonKey
 * @author Inswave
 * @date 2026. 09. 01
 * @description 첨부문서 목록 팝업에 넘길 키데이터를 정의한다
 * @param {Array} arrPar 팝업 파라미터 배열
 * @returns {Array} 팝업 파라미터 배열
 * @hidden N
*/
scwin.getCommonKey = function (arrPar) {
