 * @returns {Array} 팝업 파라미터 배열
 * @hidden N
*/
scwin.getReturn = function (arrPar) {
    arrPar[0] = {
        BND_APPL_ID: dma_detailList.get("bndApplId"),
        BND_LIST_PROCS_TP_CD: dma_detailList.get("bndListProcsTpCd"),
        ISUR_NM: dma_detailList.get("isurNm"),
        ISU_NM: dma_detailList.get("isuNm")
    };
    return arrPar;
};

/**
 * @method
 * @name scwin.setReturn
 * @author Inswave
 * @date 2026. 09. 01
 * @description 반송 팝업 결과 수신 — 성공 시 목록 재조회
 * @param {Array} arrPar 팝업 결과 배열
 * @returns
 * @hidden N
*/
scwin.setReturn = function (arrPar) {
    if ("Y" === arrPar[0].SUCCESS_YN) {
        // 팝업 프레임워크가 직접 호출하는 콜백 — 진입점 try/catch 밖이므로 자체 처리
        scwin.listSync().catch(function (ex) {
            $c.exception.handleError(ex, { context: "ULDBNS15000.setReturn" });
        });
    }
};

/**
