 * @param {Array} arrPar 팝업 파라미터 배열
 * @returns {Array} 팝업 파라미터 배열
 * @hidden N
*/
scwin.getParApprovFileWrt = function (arrPar) {
    arrPar[0] = {
        BND_APPL_ID: scwin.gBndApplId,
        BND_LIST_PROCS_TP_CD: scwin.vBndListProcsTpCd,
        BND_MKTACT_TP_CD: scwin.vMktactCd
    };
    return arrPar;
};

/**
 * @method
 * @name scwin.procBtnStat
 * @author Inswave
 * @date 2026. 09. 01
 * @description 처리 상태가 처리완료일 경우 처리완료 버튼 비활성화
 * @param
 * @returns
 * @hidden N
*/
scwin.procBtnStat = function () {
    if (tab_List.getSelectedTabIndex() === 1) { // 접수내역 탭
        if (scwin.gProcsStat === "처리완료") {
            btn_Proc.setDisabled(true);
            scwin.btnStat.Proc = "dis";
        } else {
            btn_Proc.setDisabled(false);
            scwin.btnStat.Proc = "en";
        }
    }
};

/**
 * @method
 * @name scwin.checkModAndRet
 * @author Inswave
 * @date 2026. 09. 01
 * @description 접수 후 수정 및 반송 가능 여부를 체크한다
 * @param {String} bndApplId 채권신청ID
 * @returns {Number} 0: 진행, 4: 중단(마감처리 종목)
 * @hidden N
*/
scwin.checkModAndRet = async function (bndApplId) {
    await scwin.getCheckUrl('', bndApplId, 'N');

    if (dma_rtnGetCheckUrl.get("VALID_BND") === "Y") {
        $c.win.alert("이미 마감처리가 된 종목입니다. 처리하실수 없습니다.");
        return 4;
    }

    return 0;
};

/**
 * @method
 * @name scwin.endConfirm
 * @author Inswave
 * @date 2026. 09. 01
 * @description 접수·처리완료 진행 확인
 * @param {String} hasAttachDoc 첨부문서 여부(Y/N)
 * @param {String} procsNm 처리명
 * @returns {Boolean} 확인 여부
 * @hidden N
*/
scwin.endConfirm = async function (hasAttachDoc, procsNm) {
    if (hasAttachDoc === "N") {
        return $c.win.confirm("첨부/팩스문서가 없습니다. " + procsNm + " 하시겠습니까?");
    } else {
        return $c.win.confirm($c.stf.getMessageParam("MSG-A006", procsNm));
    }
};

/**
 * @method
 * @name scwin.checkCmData
 * @author Inswave
 * @date 2026. 09. 01
 * @description 접수·처리완료·수정 시 적용일 관련 체크항목
 * @param {String} strtDd 적용일
 * @param {String} bndApplId 채권신청ID
 * @returns {Number} 0: 진행, 1~4: 중단 사유 코드
 * @hidden N
*/
scwin.checkCmData = async function (strtDd, bndApplId) {
    await scwin.getCheckUrl(strtDd, bndApplId, 'N');

    if (dma_rtnGetCheckUrl.get("VALID_STRT_DD") === "Y") {
        await $c.win.alert("적용일이 현재일자보다 작습니다. 다시 입력하십시오.");
        return 1;
    }
    if (dma_rtnGetCheckUrl.get("VALID_CALND_DD") === "Y") {
        await $c.win.alert("적용일이 매매일에 유효하지 않습니다. 다시 입력하십시오.");
        return 2;
    }
    // 적용일 전날이 아니면 확인메시지 보여주기
    if (dma_rtnGetCheckUrl.get("VALID_BF_DD") === "Y") {
        if (! await $c.win.confirm("상장일/적용일이 익영업일이 아닙니다. 처리하시겠습니까?")) {
            return 4;
        }
    }
    if (dma_rtnGetCheckUrl.get("VALID_CLS_DD") === "Y") {
        await $c.win.alert("입력한 일자는 이미 마감처리가 종료된 일자입니다. 다시 입력하십시오.");
        return 3;
    }

    return 0;
};

/**
 * @method
 * @name scwin.chgTabAct
 * @author Inswave
 * @date 2026. 09. 01
 * @description 탭 전환 시 필드 ReadOnly 속성 제거/부여
 * @param {Number} vBndListProcsTpCd 채권처리구분(1:신청,2:접수)
 * @returns
 * @hidden N
*/
scwin.chgTabAct = function (vBndListProcsTpCd) {
    // 변경후 이자율, 사유발생일
    if (vBndListProcsTpCd === 1) {
        edt_AfchgCpnIntRt.setReadOnly(true);
        edt_RsnOccrDd.setReadOnly(true);
    } else if (vBndListProcsTpCd === 2) {
        edt_AfchgCpnIntRt.setReadOnly(false);
        edt_RsnOccrDd.setReadOnly(false);
    }
};
